{
  "items": [
    {
      "title": "Duisburg City Council Information System (Ratsinformationssystem der Stadt Duisburg)",
      "url_or_doi": "https://www.duisburg.de/rathaus/rathausundpolitik/ratgremien/ratsinformationssystem",
      "justification": "Official municipal information system providing access to public council documents, meeting agendas, legislative proposals, committee proceedings, and political decisions. Historical records include documents from the 2000s, making this one of the most directly relevant sources for researching local legislation, municipal governance, and legal decision-making in Duisburg between 2000 and 2009. Records are searchable, although they are not necessarily available as downloadable structured datasets."
    },
    {
      "title": "Municipal Election Results in North Rhine-Westphalia (Kommunalwahlen)",
      "url_or_doi": "https://www.govdata.de/suche/daten/kommunalwahlen?ids=0a6c899e-cdff-4ef6-839e-fcdf26731a65&ids=3083499f-e013-45d3-aeb8-ccb9b54c8d5f",
      "justification": "Official open government dataset containing historical municipal election results in North Rhine-Westphalia, including the 2004 elections. Duisburg can be examined as an independent city within the state. The data supports research into local political representation, electoral accountability, and the composition of legislative decision-making bodies during the 2000s."
    },
    {
      "title": "Historical Municipal Council Election Results in Duisburg, 1979–2009",
      "url_or_doi": "https://www.duisburg.de/vv/medien/dez_i/TI_0514b-text.pdf",
      "justification": "Official statistical publication from the City of Duisburg containing historical municipal council election results, including 2004 and 2009. The tables report voter turnout and political party vote shares, allowing researchers to investigate changes in municipal political representation and the institutional context of local legislation during the 2000s. This is a statistical publication rather than a machine-readable dataset."
    },
    {
      "title": "German Police Crime Statistics 2009 (Polizeiliche Kriminalstatistik)",
      "url_or_doi": "https://www.bka.de/SharedDocs/Downloads/DE/Publikationen/PolizeilicheKriminalstatistik/pksJahrbuecherBis2011/pks2009.pdf?__blob=publicationFile&v=2",
      "justification": "Official criminal statistics published by Germany's Federal Criminal Police Office (Bundeskriminalamt). Includes city-level crime statistics for Duisburg, such as registered offenses, crime rates, and comparisons with 2008. Particularly relevant for examining criminal law enforcement, public safety, and the operation of the legal system in Duisburg toward the end of the 2000s. The publication contains statistical tables rather than a standalone downloadable dataset."
    },
    {
      "title": "Criminal Prosecution Statistics: Persons Tried and Convicted in North Rhine-Westphalia",
      "url_or_doi": "https://www.govdata.de/suche/daten/aufgrund-von-straftaten-abgeurteilte-und-verurteiltepersonen-land-jahr",
      "justification": "Official statistical dataset published by Information und Technik Nordrhein-Westfalen (IT.NRW), documenting persons tried and convicted of criminal offenses by year. Available in structured CSV and XML formats. Relevant for studying criminal justice outcomes, prosecution patterns, and the broader judicial environment governing Duisburg. The dataset covers North Rhine-Westphalia rather than Duisburg specifically, so it provides regional context instead of city-level measurements. Historical coverage for individual years in 2000–2009 should be checked."
    },
    {
      "title": "Duisburg City Council Rules of Procedure (Geschäftsordnung Rat der Stadt), 2005",
      "url_or_doi": "https://www.duisburg.de/rathaus/rathausundpolitik/buergerangagement_und_buergerangelegenheiten/einwohnerfragestunden.php.media/15287/Geschaeftsordnung-der-Stadt.pdf",
      "justification": "Official municipal legal document adopted by the Duisburg City Council on December 12, 2005. Establishes procedural rules governing council meetings, invitations, agendas, and legislative deliberations. Directly relevant to studying the legal and institutional framework of municipal government during the 2000s. This is a primary legal document rather than a statistical dataset."
    },
    {
      "title": "North Rhine-Westphalia Municipal Elections and Electoral Law Documentation",
      "url_or_doi": "https://www.landtag.nrw.de/files/live/sites/landtag-r20/files/Internet/I.A.4/Gesetzesdokumentation/Startseite_Gesetzesdokumentation/Numerische_und_Titeluebersicht_14._WP/070/LTNRW-19-14-070-R3.pdf",
      "justification": "Official legislative documentation concerning amendments to North Rhine-Westphalia's municipal election law. Includes historical electoral participation statistics for Duisburg in 2004. Useful for examining the relationship between state legislation, local electoral administration, and democratic representation in Duisburg during the 2000s. The document combines legal materials with historical statistical tables."
    },
    {
      "title": "Duisburg Municipal Council and Committee Records (SessionNet)",
      "url_or_doi": "https://sessionnet.owl-it.de/duisburg/bi/info.asp",
      "justification": "Public information portal for Duisburg's municipal council and committees. Provides access to administrative proceedings, political proposals, meeting documents, and council decisions. Particularly useful for investigating how local regulations and policies were proposed, discussed, and approved. Historical documents from the 2000s can be searched where available. The portal is a document repository, and a comprehensive machine-readable historical export is not confirmed."
    },
    {
      "title": "North Rhine-Westphalia Judicial and Criminal Justice Open Data Collection",
      "url_or_doi": "https://www.govdata.de/suche?groups=just&openness=has_open&sort=title_asc&tags=nordrhein-westfalen",
      "justification": "Government open-data catalog containing datasets related to justice, legal systems, criminal prosecution, and public safety in North Rhine-Westphalia. Includes statistical resources from official government providers, some available in machine-readable formats. Useful for identifying additional datasets on criminal convictions, judicial proceedings, and legal institutions that provide regional context for Duisburg during the 2000s. Geographic detail and historical coverage vary by dataset."
    }
  ]
}
